def match_parens(lst):
    def is_good(s):
        stack = []
        for c in s:
            if c == '(':
                stack.append(c)
            else:
                if not stack:
                    return False
                stack.pop()
        return not stack

    s1, s2 = lst
    return 'Yes' if is_good(s1 + s2) or is_good(s2 + s1) else 'No'
